import json,copy
from pathlib import Path
from content_helper import case,rows
rows.clear()
case('P271','A_00739',['把绿色液体从塑料瓶倒入杯中','观察握瓶、逐步倾斜与扶杯的双手协调。','瓶口到杯口的液体路径应与倾斜相关，杯应由桌面或手承托。','液体可流入并积聚，瓶口已有泡沫可变化，不要求流束完全透明或完全无泡。','若停倒或少量液体溅出，观察重力、液位与泡沫连续性。','只有倾瓶准备，实际流动不足以评价时选择无法判断。','双手倾瓶扶杯、绿色液体流动与杯内积聚'],['Pour green liquid from a plastic bottle into a glass','Consider bottle grip, progressive tilting, and glass stabilization.','The bottle-to-glass flow path should relate to tilt, with hand or table support for the glass.','Liquid may flow and accumulate, with changes in existing bottle-mouth foam. Perfect clarity or foam-free pouring is not required.','On stopping or splashing, consider gravity, liquid level, and foam continuity.','Choose unable to judge if only tilting preparation is shown and actual flow cannot be assessed.','Bottle–glass coordination, green-liquid flow, and glass accumulation'])
case('P272','A_00485',['把醒酒器中的红色液体倒入酒杯','观察坐姿、握器倾倒与杯体位置控制。','器口、流束和杯口应有合理相对位置，杯或器的支撑应连续。','液体可形成流束并在杯中积聚，不要求整器倒空或杯子移动。','若停止倾倒，观察流束中断和剩余液体，不推断画面外洒漏。','只有举器或对杯准备，实际转移不足以评价时选择无法判断。','人体倾器、红液转移与酒杯桌面支撑'],['Pour red liquid from a decanter into a wine glass','Consider seated balance, decanter grip and tilt, and glass positioning.','Opening, stream, and glass should align plausibly, with continuous vessel support.','Liquid may stream and accumulate without emptying the decanter or moving the glass.','On stopping, consider stream interruption and remaining liquid without inferring off-screen spills.','Choose unable to judge if only lifting or alignment is shown and actual transfer cannot be assessed.','Decanter control, red-liquid transfer, and glass–table support'])
case('P273','A_04187',['向有余烬的纤维火绒吹气','观察双手托持、嘴部吹气与火绒距离控制。','火绒应由手承托，吹气时烟与余烬的变化应有合理时序。','余烬可变亮、阴燃或产生火焰，不要求每次吹气都立即出现大火。','若停止吹气或火绒移开，观察烟气扩散和燃烧来源，不推断隐藏火种。','只有凑近准备，实际吹气与火绒响应不足以评价时选择无法判断。','人体吹气、纤维束承托与余烬烟气变化'],['Blow on fibrous tinder containing embers','Consider two-hand support, blowing, and distance control.','Hands should support tinder, with plausible timing of smoke and ember responses to blowing.','Embers may brighten, smolder, or ignite. Large flames after every breath are not required.','On stopping or withdrawal, consider smoke dispersal and combustion sources without inferring hidden ignition.','Choose unable to judge if only approach is shown and actual blowing and tinder response cannot be assessed.','Body blowing, fiber-bundle support, and ember–smoke changes'])
case('P274','A_03428',['在营火旁持物并操作','观察蹲姿、双手托持小物与身体平衡。','按可见手、物体和木堆的相对位置评价，不根据不可见部分指定工具或燃料。','已有微弱火焰和烟可变化，不要求重新点火或所有木柴立即燃烧。','若小物接近或离开木堆，观察连续运动及火烟来源。','物体过小、接触被遮挡且实际操作无法评价时选择无法判断。','人体低位操作、持物支撑与营火位置关系'],['Handle an object beside a campfire','Consider crouching, two-hand support of the small object, and balance.','Assess visible hand–object–pile relations without assigning an unseen tool or fuel.','Existing faint flames and smoke may vary. New ignition or immediate burning of every log is not required.','If the object approaches or leaves the pile, consider continuous motion and fire or smoke sources.','Choose unable to judge if size and occlusion prevent assessment of actual operation.','Low-level body action, object support, and campfire spatial relations'])
case('P275','A_03416',['托持正在燃烧的干火绒束','观察双手托持纤维、树皮和细枝的协调。','松散材料应由手或束内接触合理支撑，火焰应与燃烧材料相关。','火焰烟气可摆动，燃烧可局部进行，不要求短片内全部烧尽。','若束体倾斜或移开，观察松散材料保持、火焰方向及烟气扩散。','手与材料支撑或燃烧位置均无法辨认时选择无法判断。','双手承托、松散火绒结构与火焰烟气'],['Hold an actively burning dry-tinder bundle','Consider two-hand support of fibers, bark, and thin twigs.','Loose materials should have plausible hand or internal contact support, with flames related to burning material.','Flames and smoke may fluctuate and combustion may remain local. Complete consumption is not required.','On tilting or withdrawal, consider material retention, flame direction, and smoke dispersal.','Choose unable to judge if material support and burning location cannot be distinguished.','Two-hand support, loose-tinder structure, and flame and smoke'])
case('P276','A_03405',['把枝条和稻草推入炉口','观察双手推送、弯腰与身体平衡。','燃料与炉口接触及深入应与手部推压对应，炉体应合理限制位置。','枝条可滑动、草束可压缩，已有火焰可变化，不要求每根立刻燃烧。','若松手，观察燃料留置、局部掉落和烟气来源。','只有整理炉旁材料，实际送入不足以评价时选择无法判断。','人体推送、枝草炉口接触与炉内支撑'],['Push branches and straw into a stove opening','Consider two-hand feeding, leaning, and balance.','Fuel contact and entry should correspond to hand pressure, with plausible opening constraints.','Branches may slide and straw may compress while existing flames vary. Immediate ignition of every piece is not required.','On release, consider retention, local falling, and smoke sources.','Choose unable to judge if only nearby sorting is shown and actual feeding cannot be assessed.','Body feeding, branch–straw opening contact, and stove support'])
case('P277','A_03388',['吹动干草火绒使其阴燃','观察托持松散束体、俯身吹气与嘴部距离协调。','手部应合理承托火绒，烟气出现和受气流影响应与操作相关。','材料可阴燃、冒烟或局部发光，不要求短片内出现明火。','若停止吹气或移开，观察烟的扩散及束体保持，不凭微笑推断点火成功。','只有准备，实际吹气和材料响应不足以评价时选择无法判断。','人体吹气、干草束承托与阴燃烟气'],['Blow on a dry-grass tinder bundle to encourage smoldering','Consider bundle support, leaning breath, and mouth distance.','Hands should plausibly support tinder, with smoke onset and airflow response related to action.','Material may smolder, smoke, or glow locally. Open flame within the clip is not required.','On stopping or withdrawal, consider smoke dispersal and bundle retention. A smile does not establish ignition success.','Choose unable to judge if only preparation is shown and actual blowing and material response cannot be assessed.','Body blowing, grass-bundle support, and smoldering smoke'])
case('P278','A_04237',['用发圈和细带束住头发','观察双手在脑后收拢发束、拉伸发圈与穿绕的协调。','发圈或细带应在手指和发束间合理接触，不要求每段隐藏绕行清晰可见。','头发可聚拢，弹性圈可拉伸或回缩，不要求发丝改变长度。','若松手，观察发束保持或自然下垂及圈带的约束，不要求唯一发型终态。','只有展示发圈或收拢准备，实际束发不足以评价时选择无法判断。','双手束发、圈带弹性约束与发束保持'],['Secure hair with a hair tie and thin ribbon','Consider gathering behind the head, stretching the tie, and coordinated threading.','Tie or ribbon should contact fingers and hair plausibly. Hidden loops need not all be visible.','Hair may gather and elastic may stretch or retract without changing strand length.','On release, consider retention or natural hanging and tie constraints without prescribing one final hairstyle.','Choose unable to judge if only tie display or gathering preparation is shown and actual fastening cannot be assessed.','Two-hand fastening, elastic tie constraints, and hair retention'])
case('P279','A_04157',['用自动卷发器整理发束','观察一手分取发束、另一手控器与头部位置协调。','发束应在器具入口或卷筒处连续接触，器具运动应与握持相符。','头发可被卷入、弯曲或释放，不要求一次形成固定大小卷曲。','若发束退出，观察连续长度、柔性下垂和器具释放，不推断不可见温度。','只有靠近准备，实际卷绕不足以评价时选择无法判断。','双手控发控器、发束卷绕与释放连续性'],['Style a hair section with an automatic curler','Consider separating hair, controlling the tool, and head positioning.','Hair contact at the opening or roller should remain continuous, with tool motion related to grip.','Hair may wind, bend, or release without requiring a fixed curl size in one pass.','On exit, consider continuous length, flexible hanging, and release without inferring unseen temperature.','Choose unable to judge if only approach is shown and actual winding cannot be assessed.','Hair–tool coordination, strand winding, and release continuity'])
case('P280','A_03576',['用直发夹整理头发','观察一手夹持器具、另一手分束与肩臂协调。','夹板开合、发束接触和沿发移动应相关，电线应保持合理连接。','发束可被夹住、滑过或变得平顺，不要求涂抹物出现或整头立即改变。','若夹板打开或发束释放，观察头发连续性及重力下垂，不推断不可见温度。','只有器具靠近，实际夹持滑动不足以评价时选择无法判断。','双手控夹、夹板发束接触与发丝释放'],['Style hair with a flat iron','Consider tool grip, sectioning with the other hand, and arm coordination.','Plate opening, strand contact, and passage along hair should correspond, with plausible cord connection.','A section may clamp, slide, or smooth. Visible spread or immediate whole-head change is not required.','On opening or release, consider strand continuity and gravity without inferring unseen temperature.','Choose unable to judge if only approach is shown and actual clamping or sliding cannot be assessed.','Flat-iron control, plate–hair contact, and strand release'])
case('P281','A_02849',['用梳子和卷发工具整理发束','观察戴手套的手扶持发束与另一手导向工具的配合。','梳理或卷筒接触应与手的操作相关，按实际可见工具评价。','发束可分开、拉直或卷绕，不要求涂抹膏体或整头立即改变。','若工具移开，观察发丝连续、回落或保持卷曲，不要求整个发型完成。','只有展示工具，实际发束作用不足以评价时选择无法判断。','双手梳卷协调、发丝工具接触与柔性变化'],['Arrange a hair section with a comb and curling tools','Consider gloved strand support and tool guidance with the other hand.','Combing or barrel contact should correspond to hand action, using actually visible tools.','Hair may separate, straighten, or wind. Visible paste or immediate whole-head change is not required.','On withdrawal, consider strand continuity, hanging, or retained curl without requiring a completed hairstyle.','Choose unable to judge if only tools are displayed and actual hair action cannot be assessed.','Comb–curl coordination, hair–tool contact, and flexible change'])
case('P282','A_00762',['用吹风机吹整头发','观察握机、喷嘴调向和另一手拨发的协调。','喷嘴方向与头发局部响应应有合理关系，电线应连续连接。','头发可随气流摆动或逐渐蓬松，不要求看见空气本身、涂料或瞬间完全吹干。','若喷嘴移开，观察发丝回落和手部控制，不推断不可见温度或湿度。','只有持机准备，实际吹整关系不足以评价时选择无法判断。','双手吹整、喷嘴定向与发丝气流响应'],['Style hair with a hairdryer','Consider dryer grip, nozzle orientation, and hair guidance with the other hand.','Nozzle direction should relate plausibly to local hair response, with continuous cord connection.','Hair may move in airflow or gradually gain volume. Visible air, spread, or instantaneous complete drying is not required.','On nozzle withdrawal, consider strand settling and hand control without inferring unseen temperature or moisture.','Choose unable to judge if only preparation is shown and actual drying interaction cannot be assessed.','Dryer–hand coordination, nozzle direction, and hair airflow response'])
case('P283','A_03548',['用染发刷向发根涂膏','观察握刷、分发与手腕小幅导向的协调。','刷毛接触与发根处膏体转移应相关，不凭已有白膏判定本次涂抹。','膏体可附着并局部铺开，头发可随刷动弯曲，不要求立即改变发色。','若刷子离开，观察膏体保留和发丝连续，不推断化学反应是否完成。','只有刷子靠近，实际涂抹不足以评价时选择无法判断。','手部控刷、膏体转移与发根接触'],['Apply cream to hair roots with a dye brush','Consider brush grip, sectioning, and small wrist guidance.','Bristle contact should relate to root-level cream transfer. Existing white cream alone does not establish this application.','Cream may adhere and spread locally while hair bends. Immediate color change is not required.','On withdrawal, consider cream retention and strand continuity without inferring completion of chemical reactions.','Choose unable to judge if only approach is shown and actual application cannot be assessed.','Brush control, cream transfer, and root contact'])
case('P284','A_00924',['用两根细棒整理额前发束','观察双手控棒、夹取或绕动发束与头部配合。','细棒与发丝的接触应连续，头发应保持与头部或其余发束的合理连接。','发丝可分束、弯曲或绕卷，不要求硬性断裂或工具变软。','若细棒移开，观察发束释放、下垂或局部保持形状。','只有细棒对位，实际发束作用不足以评价时选择无法判断。','双手控棒、细棒发丝接触与发束柔性'],['Arrange a forehead hair section with two slender sticks','Consider two-hand stick control, gripping or winding hair, and head coordination.','Stick–hair contact should remain continuous, with plausible hair attachment to head or the remaining section.','Hair may separate, bend, or wind without rigid fracture or tool softening.','On stick withdrawal, consider release, hanging, or local shape retention.','Choose unable to judge if only positioning is shown and actual hair action cannot be assessed.','Two-hand stick control, stick–hair contact, and strand flexibility'])
case('P285','A_03588',['持握并展示一双工作手套','观察双手夹持、翻转或托住空手套的配合。','布手套应随手接触合理移动，手指、织物和两只手套的关系应连续。','空手套可折叠、下垂或局部张开，不要求像已戴在手上一样保持充实形状。','若换握或松开一侧，观察柔性、重力和剩余支撑。','手与手套的实际承托关系无法辨认时选择无法判断。','双手展示、空手套柔性与重力支撑'],['Hold and display a pair of work gloves','Consider gripping, turning, and supporting the empty gloves.','Fabric gloves should move plausibly with hand contact, maintaining continuous finger, fabric, and glove relations.','Empty gloves may fold, hang, or open locally without retaining a filled-hand shape.','On regripping or releasing one side, consider flexibility, gravity, and remaining support.','Choose unable to judge if actual hand–glove support cannot be distinguished.','Two-hand display, empty-glove flexibility, and gravity support'])
Path(__file__).with_name('batch_32.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
